<div class="program-grid"><?php foreach(public_records('programs') as $index=>$item): ?><article class="program-card"><a href="<?=detail_link($item)?>" class="program-photo" tabindex="-1" aria-hidden="true"><?php if(image_path(field($item,'image'))): ?><img src="<?=e(field($item,'image'))?>" alt="" loading="lazy"><?php else: ?><div class="program-image-empty"><?=icon('target')?></div><?php endif ?><span class="program-category"><?=e(field($item,'category'))?></span></a><div class="program-content"><span class="program-level"><?=icon('users')?><?=e(field($item,'level'))?></span><h3><a href="<?=detail_link($item)?>"><?=e($item['title'])?></a></h3><p><?=e(field($item,'summary'))?></p><a class="text-link" href="<?=detail_link($item)?>">Explore this program <?=icon('arrow')?></a></div></article><?php endforeach ?></div>
